# ── Normalisation + PCA ───────────────────────────────────────────────────────
def normalise(S, mode="max"):
    """Return (S_norm, amplitude). mode: 'max' | 'area' | 'l2' | None."""
    if mode == "max":
        amp = S.max(1, keepdims=True)
    elif mode == "area":
        amp = np.trapz(np.clip(S, 0, None), axis=1)[:, None]
    elif mode == "l2":
        amp = np.linalg.norm(S, axis=1, keepdims=True)
    else:
        amp = np.ones((len(S), 1))
    amp[amp == 0] = 1
    return S / amp, amp.ravel()

def fit_pca(S, n_pc=N_PC):
    mu = S.mean(0); Sc = S - mu
    U, sv, Vt = np.linalg.svd(Sc, full_matrices=False)
    return mu, Vt[:n_pc], (sv**2 / (sv**2).sum())[:n_pc]

def reconstruct(mu, comps, scores):
    return mu + scores @ comps

# ── Feature engineering (Q -> X) ──────────────────────────────────────────────
def f_raw(Q):       return Q.astype(float)
def f_fractions(Q):
    Q = Q.astype(float); tot = Q.sum(1, keepdims=True); return np.hstack([Q / tot, tot])
def f_clr(Q):
    Q = Q.astype(float) + EPS; lg = np.log(Q); return lg - lg.mean(1, keepdims=True)
def f_chemistry(Q):
    Q = Q.astype(float); Ag = Q[:, 0] + EPS
    return np.column_stack([(Q[:,3]+Q[:,4])/Ag, Q[:,4]/Ag, Q[:,4]/(Q[:,3]+EPS),
                            Q[:,1]/Ag, Q[:,2]/Ag, Q.sum(1)])
def f_chem_v2(Q):
    Q = Q.astype(float); Ag, PVP, Ace, Asc, BH4 = Q[:,0], Q[:,1], Q[:,2], Q[:,3], Q[:,4]
    def sr(n, d, lo, hi): return np.clip(n / (d + EPS), lo, hi)
    feats = [Ag, PVP, Ace, Asc, BH4, Ag/Q_TOTAL, PVP/Q_TOTAL, Ace/Q_TOTAL, Asc/Q_TOTAL,
             BH4/Q_TOTAL, sr(Ag,PVP,-50,50), sr(BH4,Asc,-50,50), sr(Asc+BH4,PVP,-50,50)]
    for i in range(5):
        for j in range(i+1, 5): feats.append(sr(Q[:,i], Q[:,j], -20, 20))
    for i in range(5):
        for j in range(i+1, 5): feats.append(Q[:,i] * Q[:,j])
    feats += [np.log1p(sr(Ag,PVP,0,50)), np.log1p(sr(BH4,Asc,0,50)),
              BH4/(Asc+BH4+EPS), Ace/Q_TOTAL]
    Xf = np.column_stack(feats)
    Xp = PolynomialFeatures(2, include_bias=False).fit_transform(Q)
    return np.hstack([Xf, Xp[:, Q.shape[1]:]])
FEATURE_SETS = {"raw": f_raw, "fractions": f_fractions, "clr": f_clr,
                "chemistry": f_chemistry, "chem_v2": f_chem_v2}

# ── Model zoo (isotropic Matérn-5/2 GP = BO prior) ────────────────────────────
def make_kernel():
    return (C(1.0, (1e-2, 1e4)) * Matern(1.0, (1e-2, 1e3), nu=2.5)
            + WhiteKernel(0.1, (1e-6, 1e1)))
def gp_factory():
    return make_pipeline(StandardScaler(),
                         GaussianProcessRegressor(kernel=make_kernel(), normalize_y=True,
                                                  alpha=1e-8, n_restarts_optimizer=4,
                                                  random_state=SEED))
MODELS = {
    "Ridge":            lambda: make_pipeline(StandardScaler(), Ridge(alpha=1.0)),
    "BayesianRidge":    lambda: make_pipeline(StandardScaler(), BayesianRidge()),
    "RandomForest":     lambda: RandomForestRegressor(200, max_depth=15,
                                    min_samples_split=3, random_state=SEED, n_jobs=N_JOBS),
    "ExtraTrees":       lambda: ExtraTreesRegressor(200, max_depth=15,
                                    min_samples_split=3, random_state=SEED, n_jobs=N_JOBS),
    "GradientBoosting": lambda: GradientBoostingRegressor(n_estimators=200, max_depth=5,
                                    learning_rate=0.05, subsample=0.8, random_state=SEED),
    "GP-Matern52":      lambda: gp_factory(),
    "MLP":              lambda: make_pipeline(StandardScaler(), MLPRegressor(
                                    (64,32,16), max_iter=2000, early_stopping=True,
                                    random_state=SEED)),
}
if XGBOOST_AVAILABLE:
    MODELS["XGBoost"] = lambda: xgb.XGBRegressor(n_estimators=200, max_depth=5,
                                learning_rate=0.05, subsample=0.8, colsample_bytree=0.8,
                                random_state=SEED, n_jobs=N_JOBS)

class SpectralModel:
    """One regressor per PCA component, on features(Q)."""
    def __init__(self, n, feat_fn, factory):
        self.feat = feat_fn; self.models = [factory() for _ in range(n)]
    def fit(self, Q, Y):
        X = self.feat(Q)
        for k, m in enumerate(self.models): m.fit(X, Y[:, k])
        return self
    def predict(self, Q):
        X = self.feat(Q); return np.column_stack([m.predict(X) for m in self.models])
    def predict_std(self, Q):
        X = self.feat(Q)
        try:
            return np.column_stack([m.predict(X, return_std=True)[1] for m in self.models])
        except TypeError:
            return None

# ── Cross-validation (grouped by session) ─────────────────────────────────────
def make_cv(groups, k=6):
    ng = len(np.unique(groups))
    return (LeaveOneGroupOut() if k is None else GroupKFold(n_splits=min(k, ng)))

def cv_scores(Q, scores, feat_fn, factory, groups, k=6):
    X = feat_fn(Q); cv = make_cv(groups, k)
    return np.column_stack([cross_val_predict(factory(), X, scores[:, kk], cv=cv, groups=groups)
                            for kk in range(scores.shape[1])])

def derived_lmax(wl, spec, lo=350, hi=900):
    w = (wl >= lo) & (wl <= hi); return wl[w][np.argmax(spec[:, w], axis=1)]

def benchmark(S, Q, scores, mu, comps, wl, groups, lam, k=6,
              feature_sets=None, models=None):
    feature_sets = feature_sets or FEATURE_SETS
    models = models or MODELS
    rows = []
    for fname, ffn in feature_sets.items():
        for mname, fac in models.items():
            try:
                sp = cv_scores(Q, scores, ffn, fac, groups, k)
            except Exception as e:
                print(f"  {fname:10s}|{mname:14s} FAILED: {e}"); continue
            Sp = mu + sp @ comps
            rows.append(dict(feature=fname, model=mname,
                             spec_rmse=np.sqrt(np.mean((S - Sp)**2)),
                             lmax_rmse=np.sqrt(np.nanmean((lam - derived_lmax(wl, Sp))**2))))
            print(f"  {fname:10s}|{mname:14s} spec={rows[-1]['spec_rmse']:.4f} "
                  f"lmax={rows[-1]['lmax_rmse']:5.1f}")
    return pd.DataFrame(rows)

# ── Colour (spectrum -> sRGB) + colour-map slice ──────────────────────────────
def _g(x, m, s1, s2): return np.exp(-0.5 * ((x - m) / np.where(x < m, s1, s2))**2)
def _cmf(l):
    x = 1.056*_g(l,599.8,37.9,31.0)+.362*_g(l,442.0,16.0,26.7)-.065*_g(l,501.1,20.4,26.2)
    y = .821*_g(l,568.8,46.9,40.5)+.286*_g(l,530.9,16.3,31.1)
    z = 1.217*_g(l,437.0,11.8,36.0)+.681*_g(l,459.0,26.0,13.8)
    return x, y, z
_M = np.array([[3.2406,-1.5372,-.4986],[-.9689,1.8758,.0415],[.0557,-.2040,1.0570]])
def make_colouriser(wl):
    vis = (wl >= 380) & (wl <= 780); xb, yb, zb = _cmf(wl[vis]); Yn = yb.sum()
    def rgb(a):
        T = np.clip(10**(-np.clip(a[vis], 0, None)), 0, 1)
        XYZ = np.array([(T*xb).sum(), (T*yb).sum(), (T*zb).sum()]) / Yn
        c = np.clip(_M @ XYZ, 0, 1)
        return np.clip(np.where(c <= .0031308, 12.92*c, 1.055*c**(1/2.4)-.055), 0, 1)
    return rgb

def colour_slice(ax, Q, model, mu, comps, colour, qa, qb, grid_n=44, hatch=True):
    ia, ib = FEATURES.index(qa), FEATURES.index(qb)
    others = [k for k in range(5) if k not in (ia, ib)]
    med = np.median(Q, 0); prop = med[others] / med[others].sum()
    ga = np.linspace(np.percentile(Q[:,ia],5), np.percentile(Q[:,ia],95), grid_n)
    gb = np.linspace(np.percentile(Q[:,ib],5), np.percentile(Q[:,ib],95), grid_n)
    grid = np.full((grid_n, grid_n, 5), np.nan); mask = np.zeros((grid_n, grid_n), bool)
    for iy, vb in enumerate(gb):
        for ix, va in enumerate(ga):
            rem = Q_TOTAL - va - vb
            if rem <= 0: continue
            x = np.empty(5); x[ia]=va; x[ib]=vb; x[others]=rem*prop
            grid[iy,ix]=x; mask[iy,ix]=True
    X = grid[mask]; sc = model.predict(X)
    img = np.ones((grid_n, grid_n, 3)); img[mask] = np.array([colour(mu+s@comps) for s in sc])
    ax.imshow(img, origin="lower", aspect="auto", extent=[ga[0],ga[-1],gb[0],gb[-1]])
    if hatch:
        sd = model.predict_std(X)
        if sd is not None:
            u = np.full((grid_n, grid_n), np.nan); u[mask] = sd.mean(1)
            ax.contourf(ga, gb, u, levels=[np.nanpercentile(u,80), np.nanmax(u)],
                        colors="none", hatches=["xx"], alpha=0)
    ax.scatter(Q[:,ia], Q[:,ib], s=10, facecolor="none", edgecolor="k", lw=.4, alpha=.4)
    ax.set_xlabel(f"$Q_{{{qa}}}$ (µL/s)"); ax.set_ylabel(f"$Q_{{{qb}}}$ (µL/s)")
